<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$rows=[];$stmt=$db->prepare('SELECT b.*,s.name enemy_name,d.nickname,own.name own_name FROM battle_log b LEFT JOIN digimon_species s ON s.id=b.enemy_species_id LEFT JOIN digimon_instances d ON d.id=b.digimon_id LEFT JOIN digimon_species own ON own.id=d.species_id WHERE b.owner_id=? ORDER BY b.created_at DESC LIMIT 100');$stmt->bind_param('i',$uid);$stmt->execute();$r=$stmt->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$stmt->close();pv_page_start('Battle History','battle_history.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('battle_history.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">BATTLE ARCHIVE / YOUR RESULTS</span><h1>Battle History</h1><p class="pv-subtle">Review your battles, recovered scan data and rewards.</p></div></div><section class="pv-card" style="padding:18px"><?php foreach($rows as $b):?><div class="pv-status-row"><span><?=date('Y-m-d H:i',(int)$b['created_at'])?> · <?=pv_h(strtoupper((string)$b['battle_type']))?> · <?=pv_h((string)($b['own_name']??'Digimon'))?> vs <?=pv_h((string)($b['enemy_name']??'Network Opponent'))?></span><strong><?=pv_h(strtoupper((string)$b['result']))?> · +<?=(int)$b['exp_gain']?> EXP · +<?=(int)$b['scan_gain']?>% scan · +<?=(int)$b['bits_gain']?> Bits</strong></div><?php endforeach;?><?php if(!$rows):?><div class="pv-empty">Your first battle is still ahead. Enter Cyberspace to find a wild signal.</div><?php endif;?></section></section></main></div><?php pv_page_end(); ?>
